import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee) public {
        vm.assume(callee != address(0));
        vm.assume(!_isPrecompile(callee));
        address originalCaller = msg.sender;
        try c.forward(callee, abi.encodeWithSignature("setOwner(address)", originalCaller)) {
            assertTrue(msg.sender == originalCaller, "msg.sender should remain the original caller");
