// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Setup: deploy a helper that will check msg.sender
        Helper helper = new Helper();
        vm.deal(address(c), amount);
        // Fuzz the amount of ETH to forward
        vm.assume(amount > 0);
        // Call forward with ETH and the helper's receive function
        bytes memory data = abi.encodeWithSignature("receiveForwardedEth()");
        vm.prank(address(this));
        c.forward{value: amount}(address(helper), data);
        // Property: After forward, the forwarded ETH must end up in the helper
        // (In reference, call runs in helper context, msg.value sent to helper)
        // In bug, delegatecall runs in C, so helper receives nothing
        assertTrue(address(helper).balance == amount);
    }
}

contract Helper {
    function receiveForwardedEth() external payable {
        // receives ETH from C.forward (if call is used)
        // if delegatecall used, this runs in C's context, so the Helper gets no ETH
    }
    receive() external payable {}
}

